import java.util.*;

class Solution {
    int minimumSubstringsWithoutRepeatingCharacters(String s) {
        int seg = 1;
        Set<Character> used = new HashSet<>();
        for (char c : s.toCharArray()) {
            if (used.contains(c)) { seg++; used.clear(); }
            used.add(c);
        }
        return seg;
    }
}

class Solution {
public:
    int minimumSubstringsWithoutRepeatingCharacters(string s) {
        int seg = 1;
        set<char> used;
        for (char c : s) {
            if (used.count(c)) { seg++; used.clear(); }
            used.insert(c);
        }
        return seg;
    }
};
